<script setup lang="ts">
import {computed,onMounted,ref,watch} from 'vue';
import {useRoute,useRouter} from 'vue-router';
import {managementRequest} from '../api/management';
import {useAuth} from '../stores/auth';
import {monthlyPath} from '../lib/monthly-navigation';
import AssignmentPanel from '../components/AssignmentPanel.vue';
import CycleSetupSteps from '../components/CycleSetupSteps.vue';
const auth=useAuth(),route=useRoute(),router=useRouter();
type Cycle={id:string;title:string;month:string;status:string};
type Relation={id:string;reviewer_name:string;target_name:string;reviewer_department:string;target_department:string;origin:string;status:string;manual_reason:string|null;assigned_by:string|null;assigned_at:string|null};
type Person={user_id:string;display_name:string;department_name:string};
type Edge={reviewerId:string;targetId:string;reviewerName?:string;targetName?:string;sourceType:string};
type Preview={id:string;feasible:boolean;edge_count:number;edges:Edge[];indegrees:Record<string,number>;outdegrees:Record<string,number>;limits:{minReceived:number;maxReceived:number;maxAssigned:number};shortfalls?:Array<{targetName?:string;department_name?:string;indegree:number;minIndegree:number;missing:number;reason:string}>;diagnostics?:string[]};
const cycles=ref<Cycle[]>([]),cycleId=ref(''),rows=ref<Relation[]>([]),people=ref<Person[]>([]),error=ref(''),relationError=ref(''),previewError=ref(''),loading=ref(false),busy=ref(false),readLoading=ref(false),preview=ref<Preview|null>(null),saved=ref(false),previewOpen=ref(false),search=ref(''),department=ref(''),origin=ref(''),page=ref(1),detail=ref<Relation|null>(null),serial=ref(0);
const current=computed(()=>cycles.value.find(c=>c.id===cycleId.value)),editable=computed(()=>!!current.value&&['DRAFT','PENDING_OPEN'].includes(current.value.status));
const canManage=computed(()=>auth.hasCapability('assignment.manage'));
function goAnnouncement(){if(!cycleId.value)return;router.push({path:monthlyPath('announcement',cycleId.value)});}
const names:Record<string,string>={MANUAL:'人工指定',SYSTEM:'系统分配',REPLACEMENT:'受控替补'};
const stage=(v:string)=>({DRAFT:'草稿',PENDING_OPEN:'待开始',REVIEWING:'评价中',CALIBRATING:'已截止',PARTIALLY_PUBLISHED:'部分发布',PUBLISHED:'已发布',ARCHIVED:'已归档',CANCELLED:'已撤销'} as Record<string,string>)[v]??v;
const friendly=(e:unknown)=>{const code=e instanceof Error?e.message:String(e);return ({AUTH_REQUIRED:'登录状态已失效，请刷新页面重新登录。',FORBIDDEN:'当前账号没有该周期的分配权限。',ASSIGNMENT_READ_FORBIDDEN:'当前账号没有查看正式评价关系的授权。',ASSIGNMENT_LOCKED:'周期已开始或状态已变更，不能修改草稿方案。',RUN_NOT_FEASIBLE:'当前方案未通过分配检查，请处理缺口后重新预览。',RUN_INPUT_CHANGED:'参评名单或人工指定已变化，请重新预览。',STATE_CONFLICT:(current.value?.status==='CANCELLED'?'该周期已撤销，不能修改评价分配。请到「周期管理」重启或删除它。':'周期状态已变化，请刷新后重试。'),PREVIEW_REQUIRED:'请先生成分配预览。'} as Record<string,string>)[code]??'操作失败，请检查周期状态和权限后重试。';};
const departments=computed(()=>[...new Set(rows.value.flatMap(r=>[r.reviewer_department,r.target_department]).filter(Boolean))].sort());
const filtered=computed(()=>rows.value.filter(r=>(!search.value||`${r.reviewer_name} ${r.target_name}`.includes(search.value.trim()))&&(!department.value||r.reviewer_department===department.value||r.target_department===department.value)&&(!origin.value||r.origin===origin.value)));
const pages=computed(()=>Math.max(1,Math.ceil(filtered.value.length/10))),displayed=computed(()=>filtered.value.slice((page.value-1)*10,page.value*10));
watch([search,department,origin],()=>page.value=1);
async function loadManual(id:string,token:number){if(!canManage.value||!editable.value)return;try{const d=await managementRequest<{participants:Person[]}>(`cycles/${id}/assignment/manual`);if(token===serial.value)people.value=d.participants;}catch(e){if(token===serial.value)error.value=friendly(e);}}
async function loadRelations(id:string,token:number){readLoading.value=true;relationError.value='';try{const data=await managementRequest<Relation[]>('management/assignment-relations?cycleId='+encodeURIComponent(id));if(token===serial.value)rows.value=data;}catch(e){if(token===serial.value){rows.value=[];relationError.value=friendly(e);}}finally{if(token===serial.value)readLoading.value=false;}}
async function loadSaved(id:string,token:number){if(!canManage.value||!editable.value)return;try{const d=await managementRequest<Preview|null>(`cycles/${id}/assignment/confirmed-preview`);if(token===serial.value&&d){preview.value=d;saved.value=true;}}catch(e){if(token===serial.value&&e instanceof Error&&e.message!=='FORBIDDEN')previewError.value=friendly(e);}}
watch(cycleId,async id=>{const token=++serial.value;rows.value=[];people.value=[];preview.value=null;saved.value=false;error.value='';previewError.value='';relationError.value='';page.value=1;if(!id)return;loading.value=true;await Promise.all([loadManual(id,token),loadRelations(id,token),loadSaved(id,token)]);if(token===serial.value)loading.value=false;});
async function reloadManual(){if(!cycleId.value)return;preview.value=null;saved.value=false;await loadManual(cycleId.value,serial.value);}
async function runPreview(){if(!cycleId.value||busy.value)return;const id=cycleId.value;busy.value=true;previewError.value='';try{const d=await managementRequest<Preview>(`cycles/${id}/assignment/preview`,{});if(cycleId.value===id){preview.value=d;saved.value=false;previewOpen.value=true;}}catch(e){previewError.value=friendly(e);}finally{busy.value=false;}}
async function confirmPreview(){if(!preview.value?.feasible||busy.value)return;const id=cycleId.value,runId=preview.value.id;busy.value=true;previewError.value='';try{await managementRequest(`cycles/${id}/assignment/confirm-preview`,{run_id:runId});if(cycleId.value===id){saved.value=true;previewOpen.value=false;}}catch(e){previewError.value=friendly(e);}finally{busy.value=false;}}
const personStats=computed(()=>preview.value?people.value.map(p=>({...p,assigned:preview.value?.outdegrees[p.user_id]??0,received:preview.value?.indegrees[p.user_id]??0})):[]);
const shortfallReason=(reason:string)=>({INSUFFICIENT_CANDIDATES:'可用评价人不足',REVIEWER_CAPACITY:'评价人任务容量不足',SINGLE_MEMBER_DEPARTMENT:'部门人数不足，需要跨部门补足',OTHER:'可能存在人数、重复关系或规则冲突'} as Record<string,string>)[reason]??'请检查名单及评价关系';
const cleanDiagnostic=(value:string)=>value.replace(/[0-9a-f]{8}-(?:[0-9a-f]{4}-){3}[0-9a-f]{12}/gi,'相关成员或部门').replace(/相关成员或部门->相关成员或部门/g,'指定关系');
onMounted(async()=>{try{cycles.value=await managementRequest<Cycle[]>('management/assignment-cycles');const wanted=String(route.query.cycleId??'');cycleId.value=(cycles.value.find(c=>c.id===wanted)??cycles.value.find(c=>c.status==='DRAFT')??cycles.value.find(c=>c.status==='PENDING_OPEN')??cycles.value.find(c=>c.status==='REVIEWING')??cycles.value.find(c=>c.status!=='CANCELLED')??cycles.value[0])?.id??'';}catch(e){error.value=friendly(e);}});
</script>
<template><div class="relations">
 <CycleSetupSteps v-if="current" :cycle-id="cycleId" :current="2" :status="current.status" :can-next="saved" next-label="下一步：编辑公告" next-hint="先预览并保存分配方案，再进入公告编辑" done-hint="分配方案已保存" @next="goAnnouncement"/>
 <p v-if="route.query.created==='1'" class="success" role="status">周期草稿已创建，请先配置特殊关系并预览、保存分配方案。</p>
 <div class="toolbar"><div><h2>评价关系管理</h2><p>人工指定特殊关系，系统按现行分配规则补足其余关系；正式关系在月评发起后生效。</p></div><label>评价周期 <select v-model="cycleId"><option v-if="!cycles.length" value="">暂无可管理周期</option><option v-for="c in cycles" :key="c.id" :value="c.id">{{c.title}} · {{c.month}}（{{stage(c.status)}}）</option></select></label></div>
 <p v-if="error" class="error" role="alert">{{error}}</p><p v-if="loading" role="status">正在读取参评名单与关系…</p>
 <template v-if="current"><section v-if="editable && canManage" class="panel"><h2>草稿分配</h2><p>本周期 {{people.length}} 名参评成员在当前授权范围内。先指定特殊关系，再由有全周期权限的人员预览并保存方案。</p><AssignmentPanel :key="cycleId" :cycle-id="cycleId" :editable="true" @changed="reloadManual"/><div class="preview-actions"><button class="primary" :disabled="busy" @click="runPreview">{{busy?'正在处理…':'预览系统分配'}}</button><span v-if="saved" class="success">方案已保存，发起月评时使用。 <RouterLink :to="{path:monthlyPath('cycles',cycleId),query:{panel:'config'}}">返回周期管理并启动 →</RouterLink></span><span v-else class="hint">{{preview?'预览尚未保存。':'尚未保存系统分配方案。'}}</span></div><p v-if="previewError" class="error" role="alert">{{previewError}}</p>
 <div v-if="preview" class="plan"><h3>{{saved?'已保存分配方案':'当前预览方案'}} · {{preview.edge_count}} 条关系</h3><p class="hint">当前算法：每人收到 {{preview.limits.minReceived}}–{{preview.limits.maxReceived}} 份他评，每名评价人最多 {{preview.limits.maxAssigned}} 项任务；具体数量由实际方案决定。</p><div class="scroll"><table><thead><tr><th>成员</th><th>部门</th><th>作为评价人：需完成</th><th>作为被评价人：收到</th></tr></thead><tbody><tr v-for="p in personStats" :key="p.user_id"><td>{{p.display_name}}</td><td>{{p.department_name}}</td><td>{{p.assigned}} 项</td><td>{{p.received}} 份</td></tr></tbody></table></div><button @click="previewOpen=true">查看方案详情</button></div></section>
 <section v-else-if="editable" class="panel"><p>当前账号没有人工指定权限，请联系管理员授权。</p></section>
 <section v-else class="panel"><p>周期处于{{stage(current.status)}}，草稿分配已锁定。下方显示授权范围内正式生效的关系。</p><p v-if="current.status==='CANCELLED'" class="cancel-tip">该周期已撤销，评价分配不可编辑。如需重新配置，请到「周期管理」把它<strong>重启为草稿</strong>或<strong>删除</strong>后再操作。<RouterLink :to="{path:monthlyPath('cycles',cycleId)}">前往周期管理 →</RouterLink></p></section>
 <section class="panel"><h2>已生效评价关系</h2><p class="hint">此列表仅显示双方在授权范围内的正式关系。草稿方案请在上方查看。</p><p v-if="relationError" class="error" role="alert">{{relationError}}</p><p v-else-if="readLoading">正在加载关系…</p><template v-else><div class="stats"><div><span>有效关系</span><strong>{{rows.length}}</strong></div><div><span>人工指定</span><strong>{{rows.filter(r=>r.origin==='MANUAL').length}}</strong></div><div><span>系统分配</span><strong>{{rows.filter(r=>r.origin==='SYSTEM').length}}</strong></div><div><span>受控替补</span><strong>{{rows.filter(r=>r.origin==='REPLACEMENT').length}}</strong></div></div><div class="filters"><input v-model="search" placeholder="搜索评价人或被评价人" aria-label="搜索成员"/><select v-model="department" aria-label="筛选部门"><option value="">全部部门</option><option v-for="d in departments" :key="d">{{d}}</option></select><select v-model="origin" aria-label="关系来源"><option value="">全部来源</option><option value="MANUAL">人工指定</option><option value="SYSTEM">系统分配</option><option value="REPLACEMENT">受控替补</option></select></div><div class="scroll"><table><thead><tr><th>评价人</th><th>所属部门</th><th>被评价人</th><th>所属部门</th><th>来源</th><th>操作</th></tr></thead><tbody><tr v-for="r in displayed" :key="r.id"><td>{{r.reviewer_name}}</td><td>{{r.reviewer_department}}</td><td>{{r.target_name}}</td><td>{{r.target_department}}</td><td>{{names[r.origin]}}</td><td><button @click="detail=r">查看</button></td></tr></tbody></table></div><p v-if="!filtered.length" class="hint">{{editable?'本周期尚无正式生效关系。':'当前范围没有符合条件的关系。'}}</p><div class="pagination">共 {{filtered.length}} 条 <button :disabled="page<=1" @click="page--">上一页</button> {{page}} / {{pages}} <button :disabled="page>=pages" @click="page++">下一页</button></div></template></section></template>
 <div v-if="previewOpen&&preview" class="overlay" @click.self="previewOpen=false"><section class="dialog wide" role="dialog" aria-modal="true" aria-labelledby="preview-heading"><h2 id="preview-heading">系统分配预览</h2><p>本次预览共 {{preview.edge_count}} 条关系，人工指定优先保留。{{preview.feasible?'检查通过，可保存草稿方案。':'存在分配问题，请先处理。'}}</p><ul v-if="preview.shortfalls?.length" class="error"><li v-for="s in preview.shortfalls" :key="s.targetName">{{s.targetName||'参评成员'}}（{{s.department_name||'部门未知'}}）已获得 {{s.indegree}} 份，至少需要 {{s.minIndegree}} 份，还缺 {{s.missing}} 份。{{shortfallReason(s.reason)}}。</li></ul><ul v-if="!preview.feasible && preview.diagnostics?.length" class="error"><li v-for="d in preview.diagnostics" :key="d">{{cleanDiagnostic(d)}}</li></ul><div class="scroll preview-list"><table><thead><tr><th>评价人</th><th>被评价人</th><th>来源</th></tr></thead><tbody><tr v-for="e in preview.edges" :key="e.reviewerId+'-'+e.targetId"><td>{{e.reviewerName||'参评成员'}}</td><td>{{e.targetName||'参评成员'}}</td><td>{{e.sourceType==='MANUAL'?'人工指定':'系统分配'}}</td></tr></tbody></table></div><p v-if="previewError" class="error" role="alert">{{previewError}}</p><div class="actions"><button @click="previewOpen=false">关闭</button><button v-if="!saved" class="primary" :disabled="!preview.feasible||busy" @click="confirmPreview">确认并保存方案</button></div></section></div>
 <div v-if="detail" class="overlay" @click.self="detail=null"><section class="dialog" role="dialog" aria-modal="true"><h2>关系详情</h2><p>{{detail.reviewer_name}} → {{detail.target_name}}</p><p>来源：{{names[detail.origin]}}</p><p v-if="detail.origin==='MANUAL'">指定原因：{{detail.manual_reason||'历史记录未提供'}}</p><p v-if="detail.assigned_by">指定人：{{detail.assigned_by}}</p><button @click="detail=null">关闭</button></section></div>
</div></template>
<style scoped>
.toolbar,.filters,.pagination,.preview-actions,.actions{display:flex;gap:12px;align-items:center;flex-wrap:wrap}.toolbar{justify-content:space-between;margin-bottom:18px}.toolbar h2,.panel h2{font-size:18px;margin:0 0 10px}.toolbar p,.hint{color:#718099;line-height:1.6}.panel,.dialog{background:#fff;border:1px solid #e1e8f2;border-radius:12px;padding:20px;margin-bottom:18px}.stats{display:grid;grid-template-columns:repeat(4,1fr);gap:12px;margin:16px 0}.stats>div{background:#f6f9fe;border-radius:8px;padding:14px}.stats span{display:block;color:#728099;font-size:13px}.stats strong{display:block;font-size:24px;margin-top:6px}.filters input,.filters select,.toolbar select{min-height:36px;border:1px solid #dce4ef;border-radius:6px;padding:6px 10px}.scroll{overflow:auto}table{width:100%;border-collapse:collapse;font-size:13px}th,td{text-align:left;white-space:nowrap;padding:13px;border-bottom:1px solid #edf1f7}th{background:#f4f7fc;color:#687890}button{cursor:pointer;color:#246bfd;border:0;background:transparent}.primary{background:#3370ff;color:white;padding:10px 16px;border-radius:7px}.primary:disabled{background:#a8bbed}button:disabled{color:#a4aebc}.pagination,.actions{justify-content:flex-end;margin-top:16px}.error{color:#b42318}.cancel-tip{margin:12px 0 0;padding:12px 14px;background:#fff7ed;border:1px solid #fed7aa;border-radius:8px;color:#9a3412;font-size:13px;line-height:1.7}.cancel-tip a{color:#c2410c;font-weight:600;margin-left:4px}.success{color:#218456}.overlay{position:fixed;inset:0;background:#0006;display:grid;place-items:center;z-index:1000}.dialog{width:min(440px,90vw);max-height:85vh;overflow:auto}.wide{width:min(820px,90vw)}.preview-list{max-height:350px}.plan{margin-top:20px}.preview-actions{margin-top:18px}@media(max-width:900px){.stats{grid-template-columns:repeat(2,1fr)}}
</style>
